extends Node

# 普通源码玩法规则（entity-behavior）：按 E 砍伐绑定的树。
# 砍伐时背包 wood +1，实体立即不可见且不阻挡；300 个物理帧（约 5 秒）后重新长出。
# 木头存放在世界既有背包字典，生长状态通过 snapshot/validate_state/restore 持久化。

const WOOD_ID := "wood"
const WOOD_REWARD := 1
const REGROW_FRAMES := 300
const INVENTORY_LIMIT := 999999
const LEDGER_LIMIT := 4096
const MAX_CHOPS := 4096

var _host: Node
var _entity_id := ""
var _regrow_frames := REGROW_FRAMES
var _chops := 0
var _remaining_frames := 0
var _configured := false

func configure(host: Node, definition: Dictionary) -> void:
	_host = host
	var declared: Variant = definition.get("entityIds", [])
	if declared is Array and not declared.is_empty():
		_entity_id = str(declared[0])
	_configured = not _entity_id.is_empty()
	_apply_presence()

func on_entity_interacted(entity_id: String) -> void:
	if not _configured or entity_id != _entity_id or _chopped():
		return
	if not _award_wood():
		return
	_chops = mini(_chops + 1, MAX_CHOPS)
	_remaining_frames = _regrow_frames
	_apply_presence()

func _physics_process(_delta: float) -> void:
	if not _configured or _remaining_frames <= 0:
		return
	_remaining_frames -= 1
	if _remaining_frames <= 0:
		_remaining_frames = 0
		_apply_presence()

func _chopped() -> bool:
	return _remaining_frames > 0

func _award_wood() -> bool:
	var ledger: Variant = _host.get("inventory")
	if not ledger is Dictionary:
		return false
	var counts: Dictionary = ledger
	var current := int(counts.get(WOOD_ID, 0))
	if current < 0 or current + WOOD_REWARD > INVENTORY_LIMIT:
		return false
	if not counts.has(WOOD_ID) and counts.size() >= LEDGER_LIMIT:
		return false
	counts[WOOD_ID] = current + WOOD_REWARD
	return true

func _apply_presence() -> void:
	if not _configured:
		return
	var grown := not _chopped()
	_host.set_entity_presence(_entity_id, grown, grown)

func snapshot() -> Dictionary:
	return {"chopped": _chopped(), "remainingFrames": _remaining_frames, "chops": _chops}

func validate_state(data: Dictionary) -> String:
	if not data.has("chopped") or not data.has("remainingFrames") or not data.has("chops") or data.size() != 3:
		return "Invalid tree chop state fields"
	if not data.chopped is bool:
		return "Invalid tree chop flag"
	if not _count(data.chops, 0, MAX_CHOPS):
		return "Invalid tree chop count"
	if not _count(data.remainingFrames, 0, _regrow_frames):
		return "Invalid tree regrow countdown"
	if data.chopped != (int(data.remainingFrames) > 0):
		return "Tree chop flag disagrees with its regrow countdown"
	return ""

func _count(value: Variant, minimum: int, maximum: int) -> bool:
	if not (value is int or value is float) or not is_finite(float(value)):
		return false
	var number := float(value)
	return number == floorf(number) and number >= float(minimum) and number <= float(maximum)

func restore(data: Dictionary) -> void:
	if not validate_state(data).is_empty():
		return
	_chops = int(data.chops)
	_remaining_frames = int(data.remainingFrames)
	_apply_presence()

func project_entities(state: Dictionary) -> Dictionary:
	var grown := true
	if _count(state.get("remainingFrames", 0), 0, _regrow_frames):
		grown = int(state.get("remainingFrames", 0)) <= 0
	return {_entity_id: {"visible": grown, "solid": grown}}

